package dev.aura.player;
import static org.junit.Assert.*;import org.junit.*;import org.junit.runner.RunWith;import androidx.test.ext.junit.runners.AndroidJUnit4;import androidx.test.platform.app.InstrumentationRegistry;import android.content.*;import java.util.*;import java.util.concurrent.*;import java.io.*;
@RunWith(AndroidJUnit4.class)
public class UsbVolumeMemoryTest {
 final android.app.Instrumentation inst=InstrumentationRegistry.getInstrumentation();final Context c=inst.getTargetContext();UsbVolume.Access saved;Map<String,Integer> previous=new HashMap<>();
 @Before public void setup(){saved=UsbVolume.access;var prefs=c.getSharedPreferences("playback",0);prefs.getAll().forEach((key,value)->{if(key.startsWith("usbHardwareVolume.")&&value instanceof Integer v)previous.put(key,v);});AudioSettings.init(c);AudioSettings.put("mode","usb");AudioSettings.put("perfect",true);}
 @After public void cleanup()throws Exception{main(()->{UsbVolume.access=saved;UsbVolume.disconnected();AudioSettings.put("mode","android");AudioSettings.put("perfect",false);return null;});var prefs=c.getSharedPreferences("playback",0);var edit=prefs.edit();prefs.getAll().keySet().stream().filter(k->k.startsWith("usbHardwareVolume.")).forEach(edit::remove);previous.forEach(edit::putInt);edit.commit();}
 @Test public void reconnectRestoresConfirmedHardwareValueAndSeparatesDacs()throws Exception{Fake a=new Fake("test-dac-A",-20*256);main(()->{UsbVolume.access=a;UsbVolume.refresh(c);return null;});await(()->UsbVolume.state.hardware()&&!UsbVolume.state.checking(),5000);main(()->{UsbVolume.set(40);return null;});await(()->a.current==-36*256&&UsbVolume.state.level()==40,5000);int savedValue=a.current;main(()->{a.generation++;UsbVolume.disconnected();return null;});a.current=0;main(()->{UsbVolume.refresh(c);return null;});await(()->!UsbVolume.state.checking()&&a.current==savedValue,5000);assertTrue(a.writes>=2);assertEquals(1,UsbVolume.softwareGain,0);Fake b=new Fake("test-dac-B",-12*256);main(()->{UsbVolume.disconnected();UsbVolume.access=b;UsbVolume.refresh(c);return null;});await(()->!UsbVolume.state.checking(),5000);assertEquals(-12*256,b.current);assertEquals(0,b.writes);main(()->{UsbVolume.disconnected();UsbVolume.access=a;a.generation++;a.current=0;UsbVolume.refresh(c);return null;});await(()->!UsbVolume.state.checking()&&a.current==savedValue,5000);}
 @Test public void restoreFailureKeepsSavedValueAndReportsHardwareControl()throws Exception{Fake a=new Fake("test-dac-failure",-20*256);main(()->{UsbVolume.access=a;UsbVolume.refresh(c);return null;});await(()->!UsbVolume.state.checking(),5000);main(()->{UsbVolume.set(25);return null;});await(()->a.current==-45*256,5000);main(()->{a.generation++;UsbVolume.disconnected();a.current=0;a.fail=true;UsbVolume.refresh(c);return null;});await(()->!UsbVolume.state.checking(),5000);assertTrue(UsbVolume.state.hardware());assertTrue(UsbVolume.state.message().contains("복원"));main(()->{a.generation++;UsbVolume.disconnected();a.fail=false;UsbVolume.refresh(c);return null;});await(()->!UsbVolume.state.checking()&&a.current==-45*256,5000);}
 static final class Fake implements UsbVolume.Access {volatile long generation=201;final String identity;volatile int current,writes;volatile boolean fail;Fake(String id,int current){identity=id;this.current=current;}public String identity(long expected)throws IOException{check(expected);return identity;}public long generation(){return generation;}public boolean connected(){return true;}public byte[] descriptors(long expected)throws IOException{check(expected);return new byte[]{9,4,0,0,0,1,1,0,0,10,36,6,2,1,1,2,0,0,0,9,4,1,1,1,1,2,0,0,7,36,1,1,1,1,0,7,5,1,1,(byte)192,0,1};}void check(long expected)throws IOException{if(expected!=generation)throw new IOException("Disconnected");}public void claim(long expected,int iface)throws IOException{check(expected);}public int control(long expected,int type,int request,int value,int index,byte[] bytes)throws IOException{check(expected);if(type==0x21){if(fail)throw new IOException("write failed");current=UsbVolumeProtocol.signed(bytes,0);writes++;return 2;}int v=request==0x82?-60*256:request==0x83?0:request==0x84?256:current;bytes[0]=(byte)v;bytes[1]=(byte)(v>>8);return 2;}}
 <T>T main(Callable<T> action)throws Exception{FutureTask<T> task=new FutureTask<>(action);inst.runOnMainSync(task);return task.get(15,TimeUnit.SECONDS);}void await(Callable<Boolean> condition,long timeout)throws Exception{long end=android.os.SystemClock.elapsedRealtime()+timeout;while(!condition.call()&&android.os.SystemClock.elapsedRealtime()<end)Thread.sleep(25);assertTrue(condition.call());}
}
